    "Starting inventory": "Inventaire de départ",
    "Your first interaction": "Votre première interaction",
    "Every map starts with the starting room. Create it with the button on the left.": "Chaque carte commence par la salle de départ. Créez-la avec le bouton de gauche.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Choisissez une tuile dans la palette et posez-la sur le plateau ; appuyez sur R pour la faire pivoter. Pour l'instant, placez deux tuiles différentes : elles seront sorties de la boîte et installées pendant la partie.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "Le bouton Héros (H) définit les cases de départ de nos aventuriers. Sélectionnez 2 à 4 cases dans la salle de départ.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Pour révéler la carte peu à peu, il faut créer une nouvelle salle. Elle apparaît quand un élément est utilisé, en programmant un déclencheur qui ouvre une salle. Essayons : cliquez sur le bouton Élément (O) et choisissez une porte. Ajoutez ensuite un déclencheur « Ouvrir une salle ».",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Vous avez créé votre première interaction avec le décor. Dans le jeu, le héros ouvrira la porte et libérera les tuiles de la salle suivante. Maintenant, remplissons cette salle : mettez un coffre dans une salle et programmez un déclencheur qui donne des objets aux joueurs (les autres boutons et déclencheurs attendent cela).",
    "📂 Import a save of the game (.sav)": "📂 Importer une sauvegarde du jeu (.sav)",
    "Clear all": "Tout effacer",
    "Search an item…": "Rechercher un objet…",
    "Only what the party has": "Seulement ce que le groupe a",
