    "Imported from the save": "Importé de la sauvegarde",
    "This file is not a save of the game.": "Ce fichier n'est pas une sauvegarde du jeu.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Pour un groupe de vétérans : ce qu'il possède déjà au début de la campagne, gagné lors de batailles précédentes. Le groupe le reçoit quand la campagne commence. Les objets viennent de l'Atelier (onglets Objets et Armes), les compétences de l'onglet Compétences (ou du jeu). Les réserves d'objets des cartes générées laissent de côté les objets uniques que le groupe a déjà, et le jeu ne donne jamais un objet deux fois.",
