    "Import the game’s items (all kinds together, with filters), or pick a kind to see its entries and create your own. Weapon parts are made in the Weapons tab, recipes in the Recipes tab.": "Importez les objets du jeu (toutes les catégories ensemble, avec des filtres), ou choisissez une catégorie pour voir ses entrées et créer les vôtres. Les composants d'arme se créent dans l'onglet Armes, les recettes dans l'onglet Recettes.",
