    "OGG, MP3 or WAV. Each file plays at its moment in the app: when the monster appears, when it activates, when a hero hits it and when it falls. A moment without a file stays silent. The files are exported next to the map.": "OGG, MP3 ou WAV. Chaque fichier est lu à son moment dans l'application : quand le monstre apparaît, quand il s'active, quand un héros le touche et quand il tombe. Un moment sans fichier reste silencieux. Les fichiers sont exportés à côté de la carte.",
