    "Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "Ajoutons maintenant un coffre et faisons-lui distribuer quelques objets au groupe. Les autres boutons et déclencheurs peuvent attendre leur tour.",
    "Now choose what the chest gives: in its trigger, pick the item (or another option under “What”).": "Choisissez maintenant ce que donne le coffre : dans son déclencheur, choisissez l'objet (ou une autre option sous « Quoi »).",
