    "Elements with no link": "Éléments sans lien",
    "I know my way around": "Je connais les lieux",
    "Are you sure about that?": "En êtes-vous sûr ?",
    "The tutorial walks you through the editor step by step. If you ever want to revisit it, you can repeat it from ⚙ Settings.": "Le tutoriel vous guide pas à pas dans l'éditeur. Si vous voulez le revoir un jour, vous pouvez le relancer depuis ⚙ Réglages.",
    "Yes, skip it": "Oui, passer",
    "Skip the tutorial? Everything unlocks now. If you change your mind, ⚙ Settings can run it again.": "Passer le tutoriel ? Tout se débloque maintenant. Si vous changez d'avis, ⚙ Réglages peut le relancer.",
    "Right here!": "Juste ici !",
    "With Hero (H), click the squares where the heroes start: choose 2 to 4 squares in the starting room.": "Avec Héros (H), cliquez sur les cases où commencent les héros : choisissez 2 à 4 cases dans la salle de départ.",
    "Nice work!": "Beau travail !",
    "The first room is already tied to its door: when a hero opens it, the next room appears on the table. Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "La première salle est déjà liée à sa porte : quand un héros l'ouvre, la salle suivante apparaît sur la table. Ajoutons maintenant un coffre et faisons-lui distribuer quelques objets au groupe. Les autres boutons et déclencheurs peuvent attendre leur tour.",
    "Place a Chest (Object) in a room, select it and add the “Give or take away an item” trigger. Choose what it gives the party when it is opened.": "Placez un Coffre (Élément) dans une salle, sélectionnez-le et ajoutez le déclencheur « Donner ou retirer un objet ». Choisissez ce qu'il donne au groupe quand il est ouvert.",
    "A brand-new room": "Une toute nouvelle salle",
    "The door came with its script and has already created a new room tied to it. Lay out its tiles whenever you like. Now for some monsters: the Enemy button is unlocked.": "La porte est arrivée avec son script et a déjà créé une nouvelle salle qui lui est liée. Disposez ses tuiles quand vous voulez. Place aux monstres : le bouton Ennemi est débloqué.",
    "Let’s put some monsters in a room: press Enemy (E).": "Mettons des monstres dans une salle : appuyez sur Ennemi (E).",
    "Ops!": "Oups !",
    "In the Workshop, press “Import…” and bring in about 10 monsters from the game for this map.": "Dans l'Atelier, appuyez sur « Importer… » et apportez une dizaine de monstres du jeu pour cette carte.",
    "Have a look around the other workshops if you like, then head back to Rooms (◂ Rooms).": "Jetez un œil aux autres ateliers si vous le souhaitez, puis revenez à Salles (◂ Salles).",
    "Now for the room generator. Press ✦ Generate room and click the door that will connect to the new room.": "Passons au générateur de salles. Appuyez sur ✦ Générer une salle et cliquez sur la porte qui mènera à la nouvelle salle.",
    "First move the room (drag it or use the arrows) or turn it (R). “Use this” becomes available as soon as the room has moved.": "Déplacez d'abord la salle (faites-la glisser ou utilisez les flèches) ou tournez-la (R). « Utiliser celle-ci » devient disponible dès que la salle a bougé.",
    "You have built rooms by hand, programmed objects, brought in monsters, and generated a room. Now only the campaign remains: it connects maps on the world map, with scenes, choices, and rewards between them. Press “Start a campaign” and the rest of the editor opens up.": "Vous avez construit des salles à la main, programmé des éléments, apporté des monstres et généré une salle. Il ne reste plus que la campagne : elle relie des cartes sur la carte du monde, avec des scènes, des choix et des récompenses entre elles. Appuyez sur « Commencer une campagne » et le reste de l'éditeur s'ouvre.",
    "Press “Start a campaign”: everything is unlocked from there.": "Appuyez sur « Commencer une campagne » : tout est débloqué à partir de là.",
    "Explore the story flow, a scene (and its boxes), the starting inventory, and the story variables. Then go back to Rooms (◂ Rooms) to finish.": "Explorez le fil de l'histoire, une scène (et ses bulles), l'inventaire de départ et les variables de l'histoire. Revenez ensuite à Salles (◂ Salles) pour terminer.",
    "Open the Workshop": "Ouvrir l'Atelier",
    "Other finer conditions of this feat in the game (first attack of the round, other heroes…) are kept as they are.": "Les autres conditions plus fines de cet exploit dans le jeu (première attaque du round, autres héros…) sont gardées telles quelles.",
    "Otherwise the scene is skipped (the story goes on).": "Sinon, la scène est sautée (l'histoire continue).",
    "Pick a box on the left, or add one.": "Choisissez une bulle à gauche, ou ajoutez-en une.",
    "Pick a feat on the left, import one from the game, or write a new one.": "Choisissez un exploit à gauche, importez-en un du jeu, ou écrivez-en un nouveau.",
    "Pick a kind on the left.": "Choisissez une catégorie à gauche.",
    "Pick a recipe on the left, import one from the game, or write a new one.": "Choisissez une recette à gauche, importez-en une du jeu, ou écrivez-en une nouvelle.",
    "Pick another object": "Choisir un autre élément",
    "Pillars go in the sockets of an elevated tile of this room at level {n} (the dots on its edges).": "Les piliers vont dans les encoches d'une tuile surélevée de cette salle au niveau {n} (les points sur ses bords).",
    "Pillars hold up elevated tiles: pick the level of that tile ({n} to {n}) on the ribbon first.": "Les piliers soutiennent les tuiles surélevées : choisissez d'abord le niveau de cette tuile ({n} à {n}) sur le ruban.",
    "Place the city…": "Placer la cité…",
    "Potions and one-use cards the heroes spend during a quest.": "Des potions et des cartes à usage unique que les héros dépensent pendant une quête.",
