    "The platform is a box standing on the floor: it needs no pillars.": "La plateforme est une boîte posée sur le sol : elle n'a pas besoin de piliers.",
    "The rune: damage, damage types and power": "La rune : dégâts, types de dégâts et pouvoir",
    "First effect: an ability that may trigger on hits": "Premier effet : une capacité qui peut se déclencher quand l'attaque touche",
    "Second effect: another ability that may trigger on hits": "Second effet : une autre capacité qui peut se déclencher quand l'attaque touche",
    "The spaces work together, by the game's rule for random spawns: one budget of points for all of them (intensity ÷ {n} × heroes × {n} × progression, Map setup › Balancing) decides how many monsters enter and how strong. All may enter, or just one strong monster.": "Les cases fonctionnent ensemble, selon la règle du jeu pour les apparitions aléatoires : un seul budget de points pour toutes (intensité ÷ {n} × héros × {n} × progression, Configuration de la carte › Équilibrage) décide combien de monstres entrent et leur force. Tous peuvent entrer, ou un seul monstre puissant.",
    "The workshop has no items yet.": "L'Atelier n'a pas encore d'objets.",
    "The workshop has no items yet: create or import them in the Items tab.": "L'Atelier n'a pas encore d'objets : créez-les ou importez-les dans l'onglet Objets.",
