    "Used, it leaves the board (like a point of interest in the game).": "Une fois utilisé, il quitte le plateau (comme un point d'intérêt dans le jeu).",
    "Using this object counts as an objective of the room (listed and ticked). Older maps only: use “{q}”.": "Utiliser cet élément compte comme un objectif de la salle (listé et coché). Anciennes cartes seulement : utilisez « {Q} ».",
