    "Workshop tiles (made in the Workshop)": "Tuiles de l'Atelier (créées dans l'Atelier)",
    "Worn by a hero: a card with its rule, kept in the party’s inventory.": "Porté par un héros : une carte avec sa règle, gardée dans l'inventaire du groupe.",
    "Writes the .bmap (download), then clears.": "Écrit le .bmap (téléchargement), puis efface.",
