    "Tiles can stand at levels 1, 2 and 3 (the level buttons) on": "Les tuiles peuvent se placer aux niveaux 1, 2 et 3 (les boutons de niveau) sur des",
    "; the app counts the pillars your boxes have.": "; l'application compte les piliers de vos boîtes.",
    "pillars (P)": "piliers (P)",
    "Counts": "Comptes",
    "keep a number during the map (keys found, seals broken): triggers add to them, and a map objective can wait for the total.": "gardent un nombre pendant la carte (clés trouvées, sceaux brisés) : les déclencheurs y ajoutent, et un objectif de carte peut attendre le total.",
    "Export map": "Exporter la carte",
    "The": "L'onglet",
    "Workshop (⚒)": "Atelier (⚒)",
    "Map setup": "Configuration de la carte",
    "Start a campaign": "Commencer une campagne",
    "Press": "Appuyez sur",
    "3D": "3D",
    "Hero (H)": "Héros (H)",
    "Enemy (E)": "Ennemi (E)",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Quand la salle commence, le jeu remplit ces cases avec sa propre règle pour les apparitions aléatoires : points = intensité ÷ {n} × héros × {n} × progression",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Quand la salle s'ouvre, le jeu remplit ces cases avec sa propre règle pour les apparitions aléatoires : points = intensité ÷ {n} × héros × {n} × progression",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Quand la salle s'ouvre, le jeu remplit ces cases avec sa propre règle pour les apparitions aléatoires : points = intensité ÷ {n} × héros × {n} × progression ; il prend le rang le plus élevé de la plage de la carte que les points permettent de payer (coûts {n}, {n}, {n}, {n}, {n}, {n}…), et les monstres de la réserve qui ont ce rang entrent, un par case (jusqu'à {n}), tant que les points durent. Les points restants vont à la salle équilibrée suivante. Tous peuvent entrer, ou un seul monstre puissant.",
    "{n} balanced spaces in this room": "{n} cases équilibrées dans cette salle",
    "{n} monsters, tier {n}": "{n} monstres, rang {n}",
    "{n} monster, tier {n}": "{n} monstre, rang {n}",
    "{n} monsters, tier {n} (no more miniatures)": "{n} monstres, rang {n} (plus de figurines)",
    "none: no free miniature": "aucun : pas de figurine libre",
    "Room {n} · space {n},{n}": "Salle {n} · case {n},{n}",
    "{n} rooms · side quest": "{n} salles · quête annexe",
    "A change applies while this campaign is played, to every copy of the part, also the ones bought or found later.": "Une modification s'applique pendant que cette campagne est jouée, à chaque exemplaire de la pièce, y compris ceux achetés ou trouvés plus tard.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "Choisissez un type d'arme, puis ses têtes, hampes ou prises. Ce que vous modifiez s'applique pendant que cette campagne est jouée (à chaque exemplaire de la pièce, y compris ceux achetés ou trouvés plus tard) ; ce que vous laissez reste comme dans le jeu.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later)": "Choisissez un type d'arme, puis ses têtes, hampes ou prises. Ce que vous modifiez s'applique pendant que cette campagne est jouée (à chaque exemplaire de la pièce, y compris ceux achetés ou trouvés plus tard)",
    "Here you prepare the monsters of this campaign. Only the monsters listed here can be placed on the board or drawn from the spawn pool.": "Ici, vous préparez les monstres de cette campagne. Seuls les monstres listés ici peuvent être placés sur le plateau ou tirés de la réserve d'apparition.",
    "A short list is easier to balance and to test; add more as the campaign grows.": "Une liste courte est plus facile à équilibrer et à tester ; ajoutez-en d'autres à mesure que la campagne grandit.",
    "add more as the campaign grows.": "ajoutez-en d'autres à mesure que la campagne grandit.",
    "Here you choose the items of this campaign: import them from the game, change them (name, rarity, value, damage, abilities) or create your own. Only the items listed here can be dropped by monsters, found or given by triggers, and the": "Ici, vous choisissez les objets de cette campagne : importez-les du jeu, modifiez-les (nom, rareté, valeur, dégâts, capacités) ou créez les vôtres. Seuls les objets listés ici peuvent être lâchés par les monstres, trouvés ou donnés par les déclencheurs, et la",
    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "Des objets puissants trop tôt rendent les combats faciles ; trop peu, ou des objets faibles, laissent les héros à la traîne des monstres. Choisissez-les délibérément, en pensant à la progression des héros au fil de la campagne.",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "trop peu, ou des objets faibles, laissent les héros à la traîne des monstres. Choisissez-les délibérément, en pensant à la progression des héros au fil de la campagne.",
    "Each sheet changes one of the six heroes of the game while this campaign is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "Chaque fiche modifie l'un des six héros du jeu pendant que cette campagne est jouée : nom, portrait et figurine animée. Leurs armes sont dans l'onglet Armes. Ce que vous laissez tel quel reste comme dans le jeu.",
    "The item workshop": "L'atelier des objets",
    "The monster workshop": "L'atelier des monstres",
    "is what random-item triggers draw from.": "est l'endroit où puisent les déclencheurs d'objets aléatoires.",
    "The selection of available items is essential for the balance of the game.": "La sélection des objets disponibles est essentielle pour l'équilibre du jeu.",
    "The party has it from the start of the campaign (the heroes pick it in the hero choice)": "Le groupe l'a dès le début de la campagne (les héros le choisissent lors du choix des héros)",
