    "What stays:": "Ce qui reste :",
    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "l'intensité des salles avec des monstres et des déclencheurs qui appellent des monstres de la réserve, toutes avec le même pas (de −6 à +6, toujours entre 1 et 10) ;",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "les rangs pour 1–2, 3 et 4 héros des monstres placés à la main, selon la règle du jeu (comme ⚖ Équilibrer sur un monstre).",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "la progression de la campagne, les réserves de monstres et d'objets, les monstres eux-mêmes, les éléments, les déclencheurs et les textes.",
