    "{n} (elevated)": "{n} (surélevée)",
    "{n} (floor)": "{n} (sol)",
    "Room {n}: tile {n}B: the pillar at {n},-{n} is not in a socket (warning)": "Salle {n} : tuile {n}B : le pilier en {n},-{n} n'est pas dans une encoche (avertissement)",
    "Tile {n}B": "Tuile {n}B",
    "carries {n} pillar(s)": "porte {n} pilier(s)",
    "socket {n},-{n}": "encoche {n},-{n}",
    "tile {n}B: the pillar at {n},-{n} is not in a socket (warning)": "tuile {n}B : le pilier en {n},-{n} n'est pas dans une encoche (avertissement)",
    "Kind": "Type",
    "Medium pillar (level {n})": "Pilier moyen (niveau {n})",
    "Short pillar (level {n})": "Pilier court (niveau {n})",
    "Socket {n},-{n} of tile {n}B (level {n}). It enters the game together with the tile.": "Encoche {n},-{n} de la tuile {n}B (niveau {n}). Le pilier entre dans le jeu avec la tuile.",
