    "Name": "Nom",
    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "Les nouvelles salles naissent d'un élément : sélectionnez-le, ajoutez le déclencheur « {Q} ». Choisissez une salle ici avant de toucher à ce qu'elle contient.",
