    "). Which monster of the pool enters is drawn in the game.": "). Le monstre de la réserve qui entre est tiré au sort dans le jeu.",
    "+ Another space": "+ Une autre case",
    "Intensity of this room": "Intensité de cette salle",
    "Tier range {n}–{n}, campaign progression {n} (": "Plage de rangs {n}–{n}, progression de la campagne {n} (",
    "What the game would do": "Ce que ferait le jeu",
    "When the group is defeated": "Quand le groupe est vaincu",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Quand la salle commence, le jeu remplit ces cases avec sa propre règle pour les apparitions aléatoires : points = intensité ÷ {n} × héros × {n} × progression ; il prend le rang le plus élevé de la plage de la carte que les points permettent de payer (coûts {n}, {n}, {n}, {n}, {n}, {n}…), et les monstres de la réserve qui ont ce rang entrent, un par case (jusqu'à {n}), tant que les points durent. Les points restants vont à la salle équilibrée suivante. Tous peuvent entrer, ou un seul monstre puissant.",
    "change": "modifier",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "il prend le rang le plus élevé de la plage de la carte que les points permettent de payer (coûts {n}, {n}, {n}, {n}, {n}, {n}…), et les monstres de la réserve qui ont ce rang entrent, un par case (jusqu'à {n}), tant que les points durent. Les points restants vont à la salle équilibrée suivante. Tous peuvent entrer, ou un seul monstre puissant.",
    "{n} (= spaces, default)": "{n} (= cases, par défaut)",
    "{n} balanced space in this room": "{n} case équilibrée dans cette salle",
    "{n} hero": "{n} héros",
    "{n} monster, tier {n} (too few points: the minimum)": "{n} monstre, rang {n} (trop peu de points : le minimum)",
    "Opened by:": "Ouverte par :",
    "Remove this room": "Retirer cette salle",
    "Text when revealed": "Texte à la révélation",
    "Text after the room is set up": "Texte après la mise en place de la salle",
    "Text after the board is set up": "Texte après la mise en place du plateau",
    "What the heroes find in it: a person, an object (the interaction tokens)": "Ce que les héros y trouvent : une personne, un objet (les pions Interaction)",
    "Tile {n} is in another room: reusing it here needs that room removed first": "La tuile {n} est dans une autre salle : la réutiliser ici exige d'abord de retirer cette salle",
    "give one an “{q}” trigger": "donnez à l'un d'eux un déclencheur « {Q} »",
    "no object opens this room; give one an “{q}” trigger": "aucun élément n'ouvre cette salle ; donnez à l'un d'eux un déclencheur « {Q} »",
