    "Opens": "Ouvre",
    "a new room can be created here too.": "une nouvelle salle peut aussi être créée ici.",
    "opened by “{q}”": "ouverte par « {Q} »",
    "A scene (dialogue boxes)": "Une scène (bulles de dialogue)",
    "A scene of dialogue boxes (like the story flow), your own film full screen, a sound effect of the game or your own sound file. (a scene, a video, a sound)": "Une scène de bulles de dialogue (comme le fil de l'histoire), votre propre film en plein écran, un effet sonore du jeu ou votre propre fichier son. (une scène, une vidéo, un son)",
    "A sound (game effect or your own file)": "Un son (effet du jeu ou votre propre fichier)",
    "A tile": "Une tuile",
    "A video (your own film)": "Une vidéo (votre propre film)",
    "Add / Remove…": "Ajouter / Retirer…",
    "Add a trigger to “{q}”": "Ajouter un déclencheur à « {Q} »",
    "Add or remove?": "Ajouter ou retirer ?",
    "Add what?": "Ajouter quoi ?",
    "Adds to (or removes from) the item pool or the monster spawn pool of the map, for the rest of the map. (item, monster spawn)": "Ajoute à (ou retire de) la réserve d'objets ou la réserve d'apparition des monstres de la carte, pour le reste de la carte. (objet, apparition de monstres)",
