    "Play what?": "Lire quoi ?",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "Met quelque chose sur le plateau, ou le retire, pendant la partie : tuiles, éléments, monstres, salles. (une tuile, un élément, faire apparaître des monstres, une tuile, une salle, un élément, un monstre)",
    "Remove…": "Retirer…",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "Quelque chose apparaît sur le plateau : une tuile, un élément ou des monstres. (une tuile, un élément, faire apparaître des monstres)",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "Retire quelque chose du plateau : une tuile, une salle, un élément ou des monstres. (une tuile, une salle, un élément, un monstre)",
    "What happens when a hero uses this object. Several triggers run in order.": "Ce qui se passe quand un héros utilise cet élément. Plusieurs déclencheurs s'exécutent dans l'ordre.",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "Met quelque chose sur le plateau, ou le retire, pendant la partie : tuiles, éléments, monstres, salles. (une tuile, un élément, une tuile, une salle, un élément, un monstre)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "Ce qui se passe une fois, quand le compte atteint {n} (le total du compteur). Plusieurs déclencheurs s'exécutent dans l'ordre.",
    "When the balanced group is defeated: “{q}”": "Quand le groupe équilibré est vaincu : « {Q} »",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "Un but sur cette carte, annoncé quand le monstre est vaincu et listé avec les objectifs. Un objectif ne termine pas la carte : c'est la mission qui le fait (Configuration de la carte). Un objectif peut y être choisi comme mission.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "À partir du moment où le monstre est vaincu, le compteur de rounds exécute les déclencheurs qu'il contient : tous les N rounds (autant de fois que vous l'indiquez, ou jusqu'à la fin de la carte), ou une fois, N rounds plus tard. Pour une vague, mettez « {Q} » dedans : l'apparition a son propre « {Q} ».",
    "When this monster is defeated: “{q}”": "Quand ce monstre est vaincu : « {Q} »",
    "If the test fails: “{q}”": "Si le test échoue : « {Q} »",
    "After answer {n}: “{q}”": "Après la réponse {n} : « {Q} »",
