    "Heal, damage, apply or remove a condition on a spawn group, on the monsters of this room or on all. Heroes are healed at the table (use a text).": "Soigner, blesser, appliquer ou retirer un état sur un groupe d'apparition, sur les monstres de cette salle ou sur tous. Les héros sont soignés à la table (utilisez un texte).",
    "Remove conditions": "Retirer les états",
    "Target a protected one": "Cibler un protégé",
    "Stop targeting a protected one": "Ne plus cibler un protégé",
