    "Question": "Question",
    "Then": "Ensuite",
    "each answer may show a text afterwards and have its own triggers.": "chaque réponse peut afficher un texte ensuite et avoir ses propres déclencheurs.",
    "\"{q}\": objective without its object": "« {Q} » : objectif sans son élément",
    "A counter reaches a number": "Un compteur atteint un nombre",
    "An object is used (click it)": "Un élément est utilisé (cliquez dessus)",
    "An objective does not end the map. To make it the mission, pick it in Map setup → Final mission → “{q}”.": "Un objectif ne termine pas la carte. Pour en faire la mission, choisissez-le dans Configuration de la carte → Mission finale → « {Q} ».",
    "Completed when": "Accompli quand",
    "Completed when it reaches": "Accompli quand il atteint",
    "Declared at the table": "Déclaré à la table",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”)": "Déclaré à la table : l'application affiche seulement le texte de l'objectif parmi les objectifs et ne vérifie rien d'elle-même. Il compte comme accompli quand la table le coche dans le panneau Bigorna du jeu (F{n} → « {Q} »)",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”); only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "Déclaré à la table : l'application affiche seulement le texte de l'objectif parmi les objectifs et ne vérifie rien d'elle-même. Il compte comme accompli quand la table le coche dans le panneau Bigorna du jeu (F{n} → « {Q} ») ; c'est seulement alors que la condition requise « {Q} » est remplie et, s'il a été choisi comme mission, que la carte se termine.",
    "Give each object that counts (each key, each lever) an “{q}” trigger with this counter. The mission ends by itself when the number is reached.": "Donnez à chaque élément qui compte (chaque clé, chaque levier) un déclencheur « {Q} » avec ce compteur. La mission se termine d'elle-même quand le nombre est atteint.",
    "Monsters are defeated": "Des monstres sont vaincus",
    "Object:": "Élément :",
    "Objective text": "Texte de l'objectif",
    "Of the room": "De la salle",
    "What the players must do, as shown in the objectives": "Ce que les joueurs doivent faire, tel qu'affiché dans les objectifs",
    "only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "c'est seulement alors que la condition requise « {Q} » est remplie et, s'il a été choisi comme mission, que la carte se termine.",
