    "The shop opens in its own window over the board; the next triggers run when it closes. To charge an entrance or limit who may enter, put a requirement on this trigger.": "La boutique s'ouvre dans sa propre fenêtre par-dessus le plateau ; les déclencheurs suivants s'exécutent quand elle se ferme. Pour faire payer l'entrée ou limiter qui peut entrer, mettez une condition requise sur ce déclencheur.",
    "The armory opens in its own window over the board; the next triggers run when it closes. Heroes whose weapons this map sets (Workshop) keep them.": "L'armurerie s'ouvre dans sa propre fenêtre par-dessus le plateau ; les déclencheurs suivants s'exécutent quand elle se ferme. Les héros dont cette carte fixe les armes (Atelier) les gardent.",
