    ", part": ", pièce",
    ": part": " : pièce",
    ": pick a weapon, open one of its parts and change it, or create a new part for one of the three places. The weapon itself only keeps its name.": " : choisissez une arme, ouvrez l'une de ses pièces et modifiez-la, ou créez une nouvelle pièce pour l'un des trois emplacements. L'arme elle-même ne garde que son nom.",
    "A change applies while this map is played, to every copy of the part, also the ones bought or found later.": "Une modification s'applique pendant que cette carte est jouée, à chaque exemplaire de la pièce, y compris ceux achetés ou trouvés plus tard.",
    "A different monster each time": "Un monstre différent à chaque fois",
    "A feat is a goal a hero pursues during the quests (attack with a spear {n} times, open {n} chests…). The game counts it by itself and gives the reward when it is done. Import the game’s feats (they stay as in the game; duplicate one to change it), or write new ones for any hero.": "Un exploit est un but qu'un héros poursuit pendant les quêtes (attaquer avec une lance {n} fois, ouvrir {n} coffres…). Le jeu le compte tout seul et donne la récompense quand il est accompli. Importez les exploits du jeu (ils restent comme dans le jeu ; dupliquez-en un pour le modifier), ou écrivez-en de nouveaux pour n'importe quel héros.",
    "A new head of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "Une nouvelle tête de l'Atelier pour cette arme : un objet que le groupe obtient par un déclencheur ou confectionne avec une recette",
    "A new weapon in its place": "Une nouvelle arme à sa place",
    "A recipe says what an item costs in crafting materials when the heroes craft it in the camp. Import the game’s recipes to change their costs, or write one for an item of the workshop. The party learns a recipe from a “{q}” trigger, or knows it from the start.": "Une recette indique ce qu'un objet coûte en matériaux de confection quand les héros le confectionnent au campement. Importez les recettes du jeu pour modifier leurs coûts, ou écrivez-en une pour un objet de l'Atelier. Le groupe apprend une recette par un déclencheur « {Q} », ou la connaît dès le début.",
    "A skill card is unlocked for the hero (the physical card at the table)": "Une carte de compétence est débloquée pour le héros (la carte physique à la table)",
    "A skill card is unlocked for the hero (the physical card at the table); a recipe is learned by the party.": "Une carte de compétence est débloquée pour le héros (la carte physique à la table) ; une recette est apprise par le groupe.",
    "A workshop tile is your own physical piece: once per room, reusing it in another room asks to remove the earlier one, and it takes pillars in its sockets (between two squares on a straight edge) when elevated. In the app the mod builds it as a flat tile of this shape, with your picture or colour, and the heroes walk on it like on any tile.": "Une tuile de l'Atelier est votre propre pièce physique : une fois par salle, la réutiliser dans une autre salle demande de retirer la précédente, et elle prend des piliers dans ses encoches (entre deux carrés sur un bord droit) quand elle est surélevée. Dans l'application, le mod la construit comme une tuile plate de cette forme, avec votre image ou votre couleur, et les héros marchent dessus comme sur n'importe quelle tuile.",
    "Ability": "Capacité",
    "Act": "Acte",
    "Act I": "Acte I",
    "Activation {n}": "Activation {n}",
