    "{n} in the roster": "{n} dans l'effectif",
    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "Les six profils du jeu (classe, armes, compétences et exploits) entrent dans la campagne. Chacun est joué par le héros du jeu (comme dans le jeu) ou par un héros de votre effectif, placé dans le profil depuis la fiche du héros.",
    "The six profiles of the game (class, weapons, skills and feats) go into the map. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "Les six profils du jeu (classe, armes, compétences et exploits) entrent dans la carte. Chacun est joué par le héros du jeu (comme dans le jeu) ou par un héros de votre effectif, placé dans le profil depuis la fiche du héros.",
