    "Delete hero": "Supprimer le héros",
    "The animated drawing of the game hero of its profile.": "L'illustration animée du héros du jeu de son profil.",
    "(the profile’s)": "(celui du profil)",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "Chaque arme a un seul héros dans le jeu (ses pièces, la boutique, l'inventaire et les exploits la suivent). Choisir l'arme d'un autre héros lui donne celle-ci en échange. Les valeurs viennent des armes : elles se modifient dans l'onglet Armes. Les armes appartiennent au profil : elles restent avec lui si le héros s'en va.",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "Les armes appartiennent au profil : elles restent avec lui si le héros s'en va.",
    "went back to the roster.": "est retourné dans l'effectif.",
    "Who plays this profile": "Qui joue ce profil",
