    "now plays the profile of": "joue maintenant le profil de",
    "is back in the profile.": "est de retour dans le profil.",
    "Heads, hafts and grips of the weapons, imported in a package or made here: they are in the Weapons tab, under the weapon they belong to.": "Têtes, hampes et prises des armes, importées dans un paquet ou créées ici : elles sont dans l'onglet Armes, sous l'arme à laquelle elles appartiennent.",
    "{n} new part(s)": "{n} nouvelle(s) pièce(s)",
