    "Charms a hero carries; some have an effect the app applies. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Des breloques qu'un héros porte ; certaines ont un effet que l'application applique. Seuls les objets listés dans l'Atelier peuvent être donnés par les déclencheurs, les récompenses et les dialogues, lâchés par les monstres ou confectionnés.",
    "Choose the type first: it decides the figure and the animated art in the app (the game has no others) and the behaviour rules of that family. Then the rest of the sheet opens.": "Choisissez d'abord le type : il décide de la figurine et de l'illustration animée dans l'application (le jeu n'en a pas d'autres) et des règles de comportement de cette famille. Le reste de la fiche s'ouvre ensuite.",
