    "Drag the pieces to put the weapon together as you want it": "Faites glisser les pièces pour assembler l'arme comme vous le voulez",
    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Faites glisser les pièces pour assembler l'arme comme vous le voulez ; la molette (ou le curseur) change la taille de la pièce choisie, Shift+molette, Q/E ou le curseur de rotation la font tourner, les flèches la décalent. Une pièce ne s'affiche que dans son propre cadre : ce qui en sort est coupé (affiché en transparence).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "Faites glisser les pièces pour assembler l'arme, forgez le modèle et générez les images",
    "Duplicate": "Dupliquer",
