    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later)": "Choisissez un type d'arme, puis ses têtes, hampes ou prises. Ce que vous modifiez s'applique pendant que cette carte est jouée (à chaque exemplaire de la pièce, y compris ceux achetés ou trouvés plus tard)",
