    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Des potions et des cartes à usage unique que les héros dépensent pendant une quête. Seuls les objets listés dans l'Atelier peuvent être donnés par les déclencheurs, les récompenses et les dialogues, lâchés par les monstres ou confectionnés.",
