    "Rarity": "Rareté",
    "Recalculate the other tiers from this one with the game's own curve: health grows ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} per tier, defense +{n} per tier, attack +{n} up to tier {n} and then +{n} every two tiers. With this tier alone, it creates the tiers up to {n}": "Recalculer les autres rangs à partir de celui-ci avec la courbe propre du jeu : la santé croît de ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} par rang, la défense de +{n} par rang, l'attaque de +{n} jusqu'au rang {n} puis de +{n} tous les deux rangs. Avec ce rang seul, il crée les rangs jusqu'à {n}",
