    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "Écrivez du texte simple. Les boutons insèrent les noms que l'application remplit ([monster] = le nom de ce monstre, [hero] = le nom du héros qu'il cible (ou un autre nom que l'application remplit)) et les icônes du jeu. Les mots de règle comme balafrer, terrifier ou canaliser deviennent d'eux-mêmes les termes mis en évidence du jeu.",
