    "the text is what the players read.": "le texte est ce que lisent les joueurs.",
    "the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "la molette (ou le curseur) change la taille de la pièce choisie, Shift+molette, Q/E ou le curseur de rotation la font tourner, les flèches la décalent. Une pièce ne s'affiche que dans son propre cadre : ce qui en sort est coupé (affiché en transparence).",
