    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "trop peu, ou des objets faibles, laissent les héros à la traîne des monstres. Choisissez-les délibérément, en pensant à la progression des héros au fil de la carte.",
