    "Boxes of text, questions and videos (your own films), played in a row (it goes after the selected card)": "Des bulles de texte, des questions et des vidéos (vos propres films), lues à la suite (elle se place après la fiche sélectionnée)",
    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "Bulles de « {Q} » : faites glisser depuis le ● d'une bulle (ou le ● d'une réponse) sur une autre bulle pour indiquer ce qui vient ensuite",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "Les bulles se lisent dans l'ordre des flèches, en commençant par la première. Une bulle de question crée des branches : chaque réponse mène à sa propre bulle suivante. Une bulle vidéo lit votre propre film (MP{n} ou WebM) entre les autres bulles.",
    "Build the rooms of this map": "Construire les salles de cette carte",
