    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "la cloche pend dans son support : une cloche sur la table prend le support de cloche, et avec un seul support, une seule cloche peut pendre à la fois",
    "Del deletes": "Suppr supprime",
