    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "Chaque carte, quête annexe et étape a une place ici et un type de marqueur : quête principale, quête annexe, événement narratif ou visite de la cité.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "Tout ce qui concerne cette campagne est effacé de l'éditeur, et c'est irréversible :",
    "Export campaign": "Exporter la campagne",
    "Export, then delete": "Exporter, puis supprimer",
    "Files already exported stay in the folder": "Les fichiers déjà exportés restent dans le dossier",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "Les fichiers déjà exportés restent dans le dossier ; supprimez-les là-bas si vous le souhaitez. La sauvegarde automatique cesse de suivre cette campagne, elle ne les effacera donc pas. Le jeu garde la progression de tout groupe qui l'a jouée.",
    "Fit the whole flow in the view": "Ajuster tout le fil à la vue",
