    "On the world map as": "Sur la carte du monde comme",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG ou JPG, {n}:{n} ({n}×{n} convient exactement). Elle couvre tout le cadre que montre le jeu",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG ou JPG, {n}:{n} ({n}×{n} convient exactement). Elle couvre tout le cadre que montre le jeu ; l'eau, les terres brûlées, les noms de lieux et les routes du jeu sont cachés. La brume couvre une région fixe de la carte propre du jeu (les Terres brumeuses).",
    "Place this waypoint on the world map": "Placer cette étape sur la carte du monde",
    "Plays as": "Se joue comme",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "Pointez une ligne pour allumer sa flèche. Pour voir où mène une fiche, cliquez sur son ●.",
