    "Simulation": "Simulation",
    "Stay and fill them": "Rester et les remplir",
    "Story flow": "Fil de l'histoire",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "Les choix dont la campagne se souvient d'une carte à l'autre : avoir épargné le bandit, s'être rangé du côté des rebelles, avoir pris l'anneau maudit… Un choix est défini quand le groupe choisit une réponse cochée « {Q} » (ou par une action « {Q} ») et demeure jusqu'à la fin de la campagne. Les fiches du fil de l'histoire et les déclencheurs des cartes peuvent alors n'avoir lieu que si le groupe l'a fait, ou non.",
    "The party moves on the world map (it goes after the selected card)": "Le groupe se déplace sur la carte du monde (elle se place après la fiche sélectionnée)",
    "The scene goes on with the next box when the film ends.": "La scène continue avec la bulle suivante quand le film se termine.",
    "Then:": "Ensuite :",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "Elles sont exportées telles quelles. Remplissez-les, ou supprimez celles dont vous n'avez pas besoin.",
    "Type the name of the campaign to confirm:": "Tapez le nom de la campagne pour confirmer :",
