    "Waypoint {n}": "Étape {n}",
    "What it means (a note for you)": "Ce que cela signifie (une note pour vous)",
    "When this box is shown": "Quand cette bulle est affichée",
    "World map": "Carte du monde",
    "World map position: -{n}, {n}.": "Position sur la carte du monde : -{n}, {n}.",
    "World map position: {n}, {n}.": "Position sur la carte du monde : {n}, {n}.",
    "Write the boxes of this scene": "Écrire les bulles de cette scène",
    "Write the boxes ▸": "Écrire les bulles ▸",
    "Writes the .bcamp and its maps (download), then deletes.": "Écrit le .bcamp et ses cartes (téléchargement), puis supprime.",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "Vous construisez les salles de cette carte. Choisissez une autre carte, ou ajoutez des cartes, des étapes et des dialogues, sur l'écran de campagne (« {Q} » ci-dessus).",
    "after Map {n}": "après la Carte {n}",
    "after Side quest {n}": "après la Quête annexe {n}",
    "after Waypoint {n}": "après l'Étape {n}",
    "after a waypoint it plays on arrival": "après une étape, elle se joue à l'arrivée",
    "arrows nudge the selected card (or the view)": "les flèches décalent la fiche sélectionnée (ou la vue)",
    "before anything it opens the campaign.": "avant tout, elle ouvre la campagne.",
    "campaign progression {n} (Map setup → Balancing).": "progression de la campagne {n} (Configuration de la carte → Équilibrage).",
    "double-click the background adds a box": "un double-clic sur l'arrière-plan ajoute une bulle",
    "drag from its ● onto another card to link (the target comes after)": "faites glisser depuis son ● sur une autre fiche pour lier (la cible vient après)",
    "end of the scene": "fin de la scène",
    "faded dots are the official destinations": "les points estompés sont les destinations officielles",
    "from the start": "dès le début",
    "map {n} of {n}": "carte {n} sur {n}",
    "narrator": "narrateur",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "rien n'en dépend encore : choisissez-la dans « {Q} » d'une fiche, ou comme condition requise « {Q} » d'un déclencheur de carte.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "rien ne la définit encore : cochez « {Q} » dans une bulle de question et donnez-lui ce nom. D'ici là, « {Q} » n'est jamais vrai.",
    "only a question may branch": "seule une question peut créer des branches",
    "progression {n}": "progression {n}",
    "question": "question",
    "the name is yours.": "le nom est à vous.",
    "the scenes that follow it play in the same visit.": "les scènes qui la suivent se jouent pendant la même visite.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "le fil de l'histoire : {n} fiche(s), {n} scène(s) avec leurs bulles, {n} variable(s) de l'histoire",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "l'Atelier : {n} monstre(s), {n} PNJ, {n} objet(s), {n} héros, {n} arme(s), {n} recette(s), {n} exploit(s), {n} tuile(s)/élément(s) de votre création",
    "the world map positions, the rewards, the music and videos chosen": "les positions sur la carte du monde, les récompenses, la musique et les vidéos choisies",
    "with your own map picture, draw the roads on the left": "avec votre propre image de carte, tracez les routes à gauche",
    "without a name": "sans nom",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "{n} bulle(s) : texte, questions et vidéos (vos propres films), lues l'une après l'autre dans le même cadre. Jouée à ce moment de l'histoire : après une carte, c'est la scène de clôture de la carte",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "{n} bulle(s) : texte, questions et vidéos (vos propres films), lues l'une après l'autre dans le même cadre. Jouée à ce moment de l'histoire : après une carte, c'est la scène de clôture de la carte ; après une étape, elle se joue à l'arrivée ; avant tout, elle ouvre la campagne.",
    "{n} room(s)": "{n} salle(s)",
    "{n} rooms": "{n} salles",
    "← Map {n}": "← Carte {n}",
    "→ Map {n}": "→ Carte {n}",
    "▶ Box {n}": "▶ Bulle {n}",
    "▶ Simulate": "▶ Simuler",
    "▶ video": "▶ vidéo",
    "▶ ▶ video": "▶ ▶ vidéo",
    "◂ Back to the story flow": "◂ Retour au fil de l'histoire",
    "✎ or double-click opens the card": "✎ ou un double-clic ouvre la fiche",
    "📜 Original maps": "📜 Cartes originales",
    "The quests of the game, converted into editable maps": "Les quêtes du jeu, converties en cartes modifiables",
    "✦ Generate room": "✦ Générer une salle",
    "Build a room from an archetype: three candidates to pick from": "Construire une salle à partir d'un archétype : trois candidates parmi lesquelles choisir",
    "✦ Generate map": "✦ Générer une carte",
    "✦ Generate map (experimental)": "✦ Générer une carte (expérimental)",
    "Generate a map (experimental)": "Générer une carte (expérimental)",
    "Original maps": "Cartes originales",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "Les cartes originales du jeu sont lues par le mod Bigorna depuis votre propre copie du jeu : lancez le jeu une fois avec le mod installé (l'écran titre les prépare), puis rouvrez l'éditeur depuis le dossier Editor du jeu.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "Les quêtes du jeu, converties en cartes de l'éditeur : tuiles, éléments, salles, monstres et la logique que les déclencheurs peuvent exprimer.",
    "Each map comes with notes on what was simplified (Map setup).": "Chaque carte est accompagnée de notes sur ce qui a été simplifié (Configuration de la carte).",
