    "viaduct": "viaduc",
    "🧱 Pieces in your boxes…": "🧱 Pièces dans vos boîtes…",
    "How many of each piece you have: the generators use only these, and the object buttons show how many are on the table while a room is open. A blank field uses the estimate for your boxes (shown faded); ∞ means no limit. Two boxes, or a piece made by hand: raise the number.": "Combien de chaque pièce vous avez : les générateurs n'utilisent que celles-ci, et les boutons d'élément montrent combien sont sur la table pendant qu'une salle est ouverte. Un champ vide utilise l'estimation pour vos boîtes (affichée estompée) ; ∞ signifie sans limite. Deux boîtes, ou une pièce faite à la main : augmentez le nombre.",
    "3D objects and tokens": "Éléments 3D et pions",
    "Pieces in your boxes": "Pièces dans vos boîtes",
    "Piece counts saved.": "Nombre de pièces enregistré.",
    "Pillars that hold tiles": "Piliers qui soutiennent des tuiles",
    "Map tiles": "Tuiles de carte",
    "Workshop pieces": "Pièces de l'Atelier",
    "level": "niveau",
    "Successes add up over tries (a lock, a heavy door: each try brings them closer)": "Les succès s'additionnent au fil des essais (une serrure, une lourde porte : chaque essai rapproche du but)",
    "Use the counts of the boxes": "Utiliser les nombres des boîtes",
    "Piece counts: those of the boxes chosen.": "Nombre de pièces : celui des boîtes choisies.",
    "Put the middle of the archway on tiles of this room at level {n} (its feet may hang off the tiles).": "Placez le milieu de l'arcade sur des tuiles de cette salle au niveau {n} (ses pieds peuvent dépasser des tuiles).",
    "Workshop object": "Élément de l'Atelier",
