    "runes that carry you away": "des runes qui vous emportent",
    "Each answer only once (a search: the answer chosen greys out, the others stay)": "Chaque réponse une seule fois (une fouille : la réponse choisie devient grise, les autres restent)",
    "When every answer was used": "Quand toutes les réponses ont été utilisées",
    "Nothing more to do here.": "Plus rien à faire ici.",
