    "at full strength": "à pleine puissance",
    "a hero starts next to a point of interest: it fires at once (warning)": "un héros commence à côté d'un point d'intérêt : il se déclenche immédiatement (avertissement)",
    "on the table": "sur la table",
    "in your boxes": "dans vos boîtes",
    "points of interest and interaction tokens share the same tokens": "les points d'intérêt et les pions Interaction partagent les mêmes pions",
    "More than your boxes hold": "Plus que ce que contiennent vos boîtes",
    "🧱 Terrain in your boxes…": "🧱 Terrain dans vos boîtes…",
    "How many pieces of each kind of 3D terrain your boxes hold: the object buttons show how many are on the table.": "Combien de pièces de chaque type de terrain 3D contiennent vos boîtes : les boutons d'élément montrent combien sont sur la table.",
    "Terrain in your boxes": "Terrain dans vos boîtes",
    "Explore / sight tokens": "Pions Exploration / Vue",
    "The rulebooks give 46 terrain pieces in the Act I box and 34 in The Betrayer’s War; the split by kind below is an estimate. Count your own pieces and correct the numbers: the object buttons show how many are on the table while a room is open.": "Les livrets de règles indiquent 46 pièces de terrain dans la boîte de l'Acte I et 34 dans La Guerre du Traître ; la répartition par type ci-dessous est une estimation. Comptez vos propres pièces et corrigez les nombres : les boutons d'élément montrent combien sont sur la table pendant qu'une salle est ouverte.",
    "Use the estimate": "Utiliser l'estimation",
    "Save": "Enregistrer",
    "Terrain counts: the estimate for your boxes.": "Nombre de terrains : l'estimation pour vos boîtes.",
    "Terrain counts saved.": "Nombre de terrains enregistré.",
    "Place it on the board": "La placer sur le plateau",
    "Left": "Gauche",
