    "The one with the same name": "Celui qui porte le même nom",
    "Cut from the bottom": "Coupe par le bas",
    "The scenes show the portrait.": "Les scènes affichent le portrait.",
    "An empty place: define a skill": "Un emplacement vide : définissez une compétence",
    "Click a skill to add it to this hero (one of another hero comes as a copy).": "Cliquez sur une compétence pour l'ajouter à ce héros (celle d'un autre héros arrive comme copie).",
    "Define skills": "Définir des compétences",
