    "No skill found.": "Aucune compétence trouvée.",
    "No skill of this cost: add one from the column on the left, or make a new one.": "Aucune compétence de ce coût : ajoutez-en une depuis la colonne de gauche, ou créez-en une nouvelle.",
    "Search a skill…": "Rechercher une compétence…",
    "Skills of": "Compétences de",
