    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "Cela efface tout ce que garde l'éditeur : la carte ou la campagne à l'écran, l'Atelier (monstres, objets, matériaux, éléments, importés ou créés), les paquets (dans l'application : le dossier Pacotes, chaque paquet qu'il contient), les images gardées par l'éditeur, la sauvegarde rapide, vos archétypes, les astuces et avertissements, les positions et tailles des fenêtres, l'auteur, le dossier d'export et la sauvegarde automatique.",
    "Reset everything: the work on screen, the Workshop and the packages, the pictures kept, the quick save, archetypes, tips and warnings, window positions and sizes, author, export folder and autosave. The language stays.": "Tout réinitialiser : le travail à l'écran, l'Atelier et les paquets, les images gardées, la sauvegarde rapide, les archétypes, les astuces et avertissements, les positions et tailles des fenêtres, l'auteur, le dossier d'export et la sauvegarde automatique. La langue est conservée.",
