    "it stands on the game box of Act I, with its floor at level 3 and its walls 2 above. It takes no pillars.": "elle repose sur la boîte de jeu de l'Acte I, avec son sol au niveau 3 et ses murs 2 au-dessus. Elle ne prend pas de piliers.",
